// DeleteOne soft deletes a single LineItem record by ID
func (r *LineItemRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE "lineItem" SET "deletedAt" = $1 WHERE id = $2 AND "deletedAt" IS NULL`
	queryArgs := []interface{}{time.Now(), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteMany soft deletes multiple LineItem records matching the filter
func (r *LineItemRepository) DeleteMany(ctx context.Context, filter *LineItemFilter) (int, error) {
	if !HasUserID(ctx) {
		return 0, ErrNoUserInContext
	}

	// Build WHERE clause
	values := []interface{}{time.Now()}
	whereClause := filter.buildWhereClause(&values, 1)

	if whereClause == "" {
		whereClause = " WHERE \"deletedAt\" IS NULL"
	} else {
		whereClause += " AND \"deletedAt\" IS NULL"
	}
	query := fmt.Sprintf(`UPDATE "lineItem" SET "deletedAt" = $1%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}

